const sourceUrl = 'https://www.bilibili.com/v/popular/rank/all';
const biliAccountId = 10;
let accountKey = '';
const requestedCount = Number(tobub.params.maxItems ?? 100);
const collectedAt = new Date().toISOString();

const emptyResult = (status, page, message, verificationEncountered, verificationWaitSeconds) => ({
  status, sourceUrl, pageTitle: page?.pageTitle || '', accountKey, collectedAt,
  requestedCount: Number.isInteger(requestedCount) ? requestedCount : 100,
  listItemCount: page?.cardCount || 0, extractedCount: 0, persistedCount: 0,
  databaseReadbackCount: 0, invalidRecordCount: 0, duplicateCount: 0,
  failureCount: 0, extractionFailedCount: 0, extractionNotReadyCount: 0, extractionErrorSample: [],
  challengeDetected: Boolean(page?.challengeDetected), verificationEncountered, verificationWaitSeconds, message, records: []
});

if (!Number.isInteger(requestedCount) || requestedCount < 1 || requestedCount > 100) {
  return emptyResult('blocked', null, '采集条数必须是 1–100 的整数，未访问页面或写入数据库。', false, 0);
}
let biliAccount;
try {
  biliAccount = await tobub.db.getAccountById(biliAccountId);
} catch {
  return emptyResult('blocked', null, '无法读取 Tobub 的 bili 账号配置，未访问页面或写入数据库。', false, 0);
}
accountKey = String(biliAccount?.account_key ?? '');
if (accountKey !== 'bili' || Number(biliAccount?.is_active) !== 1) {
  return emptyResult('blocked', null, 'Tobub 账号配置不匹配或已停用；请在当前环境选择有效的 bili 账号/Profile。', false, 0);
}

let page = { pageTitle: '', pageUrl: sourceUrl, cardCount: 0, challengeDetected: false };
let verificationEncountered = false;
const waitStartedAt = Date.now();
const waitDeadline = waitStartedAt + 90000;
const snapshotExpression = [
  '() => {',
  "  const bodyText = (document.body?.innerText || '').replace(/\\s+/g, ' ').trim();",
  "  const challengeDetected = /请在下图依次点击|安全验证|验证码|人机验证|访问异常/.test(bodyText);",
  "  return { pageTitle: document.title || '', pageUrl: location.href, cardCount: document.querySelectorAll('.rank-list > li.rank-item').length, challengeDetected };",
  '}'
].join('\n');

try {
  await tobub.atoms.navigate({ url: sourceUrl, waitUntil: 'domcontentloaded' });
} catch {
  return emptyResult('blocked', page, '打开 Bilibili 榜单失败，未写入数据库。', false, 0);
}

while (Date.now() < waitDeadline) {
  try {
    const evaluated = await tobub.atoms.evaluate({ mode: 'function', expression: snapshotExpression });
    page = evaluated?.value ?? evaluated;
  } catch {
    return emptyResult('blocked', page, '读取榜单页面状态失败，未写入数据库。', verificationEncountered, Math.round((Date.now() - waitStartedAt) / 1000));
  }
  if (page.challengeDetected) verificationEncountered = true;
  if (!page.challengeDetected && page.cardCount > 0) break;
  await tobub.atoms.waitFor({ delay: 1500 });
}

const verificationWaitSeconds = Math.round((Date.now() - waitStartedAt) / 1000);
if (page.challengeDetected) {
  return emptyResult('blocked', page, 'Bilibili 安全验证尚未完成。可在当前可见浏览器中人工完成后重新运行；本次未写入数据库。', verificationEncountered, verificationWaitSeconds);
}
if (!page.cardCount) {
  return emptyResult('blocked', page, '等待 90 秒后仍未加载全站热门榜单，未写入数据库；请检查网络或页面结构。', verificationEncountered, verificationWaitSeconds);
}
if (!page.pageUrl.startsWith('https://www.bilibili.com/')) {
  return emptyResult('blocked', page, '页面跳转到非 Bilibili 地址，已停止采集且未写入数据库。', verificationEncountered, verificationWaitSeconds);
}

let extraction;
try {
  extraction = await tobub.atoms.extractList({
    itemSelector: '.rank-list > li.rank-item',
    readinessSelector: '.info > a.title',
    maxItems: requestedCount,
    idField: 'bvid',
    dedupe: 'field',
    dedupeFields: ['bvid'],
    includeErrors: true,
    errorPolicy: 'skip',
    fields: [
      { name: 'rank', selector: '.img .num', source: 'text', parse: 'number', required: true },
      { name: 'bvid', selector: '.info > a.title', source: 'href', transforms: [{ type: 'match', pattern: { pattern: '/video/(BV[a-zA-Z0-9]+)', flags: 'i' }, groupIndex: 1 }], required: true },
      { name: 'title', selector: '.info > a.title', source: 'text', transforms: [{ type: 'normalizeWhitespace' }, { type: 'trim' }], required: true },
      { name: 'url', selector: '.info > a.title', source: 'href', transforms: [{ type: 'absoluteUrl', baseUrl: sourceUrl }], required: true },
      { name: 'coverUrl', selector: '.img img.cover', source: { attr: 'src' }, transforms: [{ type: 'absoluteUrl', baseUrl: sourceUrl }], fallback: '' },
      { name: 'author', selector: '.detail .up-name', source: 'text', transforms: [{ type: 'normalizeWhitespace' }, { type: 'trim' }], fallback: '' },
      { name: 'authorUrl', selector: '.detail a[href*="space.bilibili.com"]', source: 'href', transforms: [{ type: 'absoluteUrl', baseUrl: sourceUrl }], fallback: '' },
      { name: 'playCount', selector: '.detail-state > .data-box', nth: 0, source: 'text', transforms: [{ type: 'normalizeWhitespace' }, { type: 'trim' }], fallback: '' },
      { name: 'danmakuCount', selector: '.detail-state > .data-box', nth: 1, source: 'text', transforms: [{ type: 'normalizeWhitespace' }, { type: 'trim' }], fallback: '' }
    ]
  });
} catch {
  return emptyResult('blocked', page, 'Tobub 结构化提取失败，未写入数据库。页面结构可能已变化。', verificationEncountered, verificationWaitSeconds);
}

const extractedRows = extraction.records || [];
const records = extractedRows
  .map(record => {
    const fields = { ...(record.fields || {}), ...(record.jsonFields || {}) };
    return {
      rank: Number(fields.rank),
      bvid: String(fields.bvid || ''),
      title: String(fields.title || '').slice(0, 300),
      url: String(fields.url || ''),
      coverUrl: String(fields.coverUrl || ''),
      author: String(fields.author || '').slice(0, 120),
      authorUrl: String(fields.authorUrl || ''),
      playCount: String(fields.playCount || ''),
      danmakuCount: String(fields.danmakuCount || '')
    };
  })
  .filter(item => Number.isInteger(item.rank) && item.rank > 0 && /^BV[a-zA-Z0-9]+$/.test(item.bvid) && item.title && item.url)
  .sort((a, b) => a.rank - b.rank);

const extractionFailedCount = extraction.failedCount || 0;
const extractionNotReadyCount = extraction.notReadyCount || 0;
const extractionErrorSample = (extraction.errors || []).slice(0, 5).map(error => String(error.field || 'record') + '@' + String(error.index ?? '?') + ': ' + String(error.message || '提取失败'));
const invalidRecordCount = extractionFailedCount + extractionNotReadyCount + (extractedRows.length - records.length);
const duplicateCount = extraction.duplicateCount || 0;
if (!records.length) {
  const result = emptyResult('blocked', page, '未提取到包含有效排名、BVID 和标题的记录，未写入数据库。', verificationEncountered, verificationWaitSeconds);
  result.invalidRecordCount = invalidRecordCount;
  result.duplicateCount = duplicateCount;
  result.extractionFailedCount = extractionFailedCount;
  result.extractionNotReadyCount = extractionNotReadyCount;
  result.extractionErrorSample = extractionErrorSample;
  return result;
}

let persistedCount = 0;
let databaseReadbackCount = 0;
let failureCount = 0;
const savedRecords = [];

for (const item of records) {
  let persisted = false;
  try {
    const saved = await tobub.db.saveContent({
      platform: 'bilibili',
      contentType: 'video',
      externalId: item.bvid,
      title: item.title,
      summary: item.author,
      url: item.url,
      metadata: {
        source: 'popular_rank_all', rank: item.rank, bvid: item.bvid,
        author: item.author, authorUrl: item.authorUrl,
        playCount: item.playCount, danmakuCount: item.danmakuCount,
        coverUrl: item.coverUrl, collectedAt
      },
      rawData: { ...item, sourceUrl, collectedAt },
      tags: ['热门榜', '全站'],
      observationSource: 'bilibili_popular_rank_all',
      observationMeta: { sourceUrl, scope: '全站热门榜', rank: item.rank, collectedAt },
      displayPath: '全站热门榜/第' + item.rank + '名',
      sortOrder: item.rank
    });
    if (!saved?.contentItemId || !saved?.observationId) throw new Error('数据库未返回记录 ID');

    const stored = await tobub.db.getContentItemByExternalId('bilibili', 'video', item.bvid);
    if (stored?.platform === 'bilibili' && stored?.content_type === 'video' && stored?.external_id === item.bvid && stored?.title === item.title) {
      persisted = true;
      persistedCount++;
      databaseReadbackCount++;
    } else {
      failureCount++;
    }
  } catch {
    failureCount++;
  }
  savedRecords.push({ ...item, persisted });
}

const complete =
  page.cardCount >= requestedCount &&
  records.length === requestedCount &&
  invalidRecordCount === 0 &&
  duplicateCount === 0 &&
  persistedCount === records.length &&
  failureCount === 0;

return {
  status: complete ? 'complete' : 'partial',
  sourceUrl,
  pageTitle: page.pageTitle || '',
  accountKey,
  collectedAt,
  requestedCount,
  listItemCount: page.cardCount,
  extractedCount: records.length,
  persistedCount,
  databaseReadbackCount,
  invalidRecordCount,
  duplicateCount,
  failureCount,
  extractionFailedCount,
  extractionNotReadyCount,
  extractionErrorSample,
  challengeDetected: Boolean(page.challengeDetected),
  verificationEncountered,
  verificationWaitSeconds,
  message: complete
    ? '已使用 bili 账号/Profile 采集并逐条回读确认 ' + persistedCount + ' 条全站热门榜记录。'
    : '采集不完整：榜单 ' + page.cardCount + ' 条，提取 ' + records.length + ' 条，数据库确认 ' + persistedCount + ' 条。',
  records: savedRecords
};
